"""Contract tests for the feedstocks generated by the ctt answer sets."""

import json
import re
import tomllib
from pathlib import Path
from typing import Any

import yaml
from conftest import COPIER, ROOT, VERSION, Feedstock, uses_lines

# The SDK pin is no longer answerable per feedstock, so the template is the only source.
SDK_VERSION = COPIER["bookshelf_sdk_version"]["default"]


def test_generated_feedstock_uses_record_and_replay_shape(feedstock: Feedstock) -> None:
    """The generated project exposes the resolved record and replay contract."""
    build = feedstock.read("build.py")
    pyproject = feedstock.read("pyproject.toml")
    ruff = feedstock.read("ruff.toml")
    makefile = feedstock.read("Makefile")

    assert "import bookshelf" in build
    assert "build = bookshelf.setup()" in build
    assert 'raw = build.use("raw")' in build
    assert (
        'build.book.write("data", processed_data, type="timeseries", used=[raw])'
        in build
    )
    assert "build.book.publish()" in build
    # The recipe states the version and the visibility, so the build file does not.
    assert "version =" not in build
    assert "visibility=" not in build
    assert "asyncio" not in build
    assert "async def" not in build
    assert "await " not in build
    # The SDK is a beta on PyPI, so the specifier names it
    # and nothing sources it from git.
    assert f'"bookshelf[publish,dataframes]=={SDK_VERSION}"' in pyproject
    assert "[tool.uv.sources]" not in pyproject
    # New releases soak for three days before uv resolves them, except the SDK itself.
    uv = tomllib.loads(pyproject)["tool"]["uv"]
    assert uv["exclude-newer"] == "3 days"
    assert uv["exclude-newer-package"] == {"bookshelf": False}
    assert '"build.py" = [' in ruff
    assert '"E402"' in ruff
    assert 'src = [\n    ".",' in ruff
    assert 'known-first-party = [\n    "build",' in ruff
    assert "VERSION ?= v0.1.0" in makefile
    assert "BUNDLE := bundle/$(VERSION)" in makefile
    assert (
        "uv run bookshelf record --force --version $(VERSION) --bundle $(BUNDLE)"
        in makefile
    )
    assert "uv run bookshelf validate $(BUNDLE)" in makefile
    # Publication is the platform's, so a feedstock carries no publish target.
    assert "bookshelf publish" not in makefile


def test_generated_recipe_declares_one_book_reading_the_checked_in_input(
    feedstock: Feedstock,
) -> None:
    """The scaffold is a working feedstock, so the recipe names a book and an input."""
    recipe = feedstock.recipe

    assert recipe["volume"]["name"] == feedstock.answers["dataset_name"]
    assert recipe["build"]["notebook"] == "build.py"
    assert recipe["defaults"]["visibility"] == "public"
    assert recipe["defaults"]["resources"]["raw"]["type"] == "tabular"
    assert [book["version"] for book in recipe["books"]] == [VERSION]

    book = feedstock.book(VERSION)
    assert book["license"] == "CC-BY-4.0"
    assert book["resources"]["raw"] == {"path": "inputs/raw.csv"}
    assert (feedstock.path / "inputs" / "raw.csv").is_file()


def test_generated_feedstock_carries_no_python_beyond_the_build_file(
    feedstock: Feedstock,
) -> None:
    """The CLI owns record, validate and replay, so a feedstock ships no scripts."""
    shipped = [path for path in feedstock.shipped() if path.endswith(".py")]

    assert not (feedstock.path / "scripts").exists()
    assert shipped == ["build.py"]


def test_generated_example_input_is_seeded_with_the_dataset_name(
    feedstock: Feedstock,
) -> None:
    """Registration deduplicates on content, so the example differs per feedstock."""
    assert feedstock.answers["dataset_name"] in feedstock.read("inputs/raw.csv")


def test_example_inputs_never_collide_between_feedstocks(
    feedstocks: list[Feedstock],
) -> None:
    """Two feedstocks must not register byte identical example resources.

    Registration deduplicates on content, so a shared example aliases onto whichever
    feedstock published it first, and the second one can then not attach it.
    """
    contents = [generated.read("inputs/raw.csv") for generated in feedstocks]

    assert len(set(contents)) == len(contents)


def test_generated_feedstock_calls_reusable_workflows(feedstock: Feedstock) -> None:
    """The generated project owns triggers and delegates workflow implementation."""
    ci = feedstock.read(".github/workflows/feedstock-ci.yaml")

    assert "pull_request:" in ci
    assert "push:" in ci
    assert "schedule:" in ci
    assert (
        "climate-resource/copier-bookshelf-dataset/.github/workflows/"
        "feedstock-ci.yaml@HEAD" in ci
    )
    assert not (feedstock.path / ".github/workflows/feedstock-publish.yaml").exists()

    workflow = yaml.safe_load(ci)
    assert workflow["permissions"] == {"contents": "read", "id-token": "write"}
    assert set(workflow["jobs"]) == {"bookshelf"}
    job = workflow["jobs"]["bookshelf"]
    assert job["name"] == "Bookshelf"
    assert set(job) == {"name", "uses", "with"}
    assert job["with"] == {
        "recipes": " ".join(
            ["bookshelf.yaml"]
            + [f"bookshelf-{name}.yaml" for name in feedstock.answers["extra_recipes"]]
        ),
        "main-ref": "main",
        "api-base-url": "${{ vars.BOOKSHELF_API_URL"
        " || 'https://bookshelf.climateresource.com.au' }}",
        "sdk-version": SDK_VERSION,
    }
    triggers = workflow[True]
    assert triggers["pull_request"]["types"] == ["opened", "synchronize", "reopened"]
    assert triggers["push"]["branches"] == ["main"]
    assert triggers["schedule"] == [{"cron": "17 3 * * 1"}]
    assert "workflow_dispatch" in triggers
    for forbidden in (
        "secrets:",
        "pull-requests:",
        "environment:",
        "TOKEN_URL",
        "withdraw",
        "steps:",
    ):
        assert forbidden not in ci


def test_caller_templates_derive_the_reusable_workflow_ref() -> None:
    """A caller uses Copier's selected ref, with its resolved commit as fallback."""
    template_workflows = ROOT / "template" / ".github" / "workflows"

    caller = (template_workflows / "feedstock-ci.yaml.jinja").read_text()

    assert "_copier_conf.vcs_ref or _copier_answers._commit" in caller


def test_template_keeps_the_generated_lock_file_under_version_control() -> None:
    """CI syncs a feedstock with --locked, so its lock file has to be committed."""
    ignored = (ROOT / "template" / ".gitignore").read_text().splitlines()

    assert "uv.lock" not in {line.strip() for line in ignored}


def test_the_rendered_fixtures_carry_no_build_products(
    feedstocks: list[Feedstock],
) -> None:
    """ctt renders files, and nothing else. `make initial-setup` writes the rest."""
    for generated in feedstocks:
        assert not (generated.path / "uv.lock").exists()
        assert not (generated.path / ".git").exists()
        assert not (generated.path / "bundle").exists()


def test_answer_sets_only_add_the_requested_recipe_files(
    feedstocks: list[Feedstock],
) -> None:
    """Extra recipes are the only optional files in a feedstock."""
    reference = set(
        next(item for item in feedstocks if item.name == "defaults").shipped()
    )
    for generated in feedstocks:
        extra = {
            f"bookshelf-{name}.yaml" for name in generated.answers["extra_recipes"]
        }
        assert set(generated.shipped()) == reference | extra
        assert bool(extra) == (generated.name == "multi-volume")
        for name in generated.answers["extra_recipes"]:
            recipe = yaml.safe_load(generated.read(f"bookshelf-{name}.yaml"))
            assert recipe["volume"] == {
                **generated.recipe["volume"],
                "name": name,
                "keywords": [name],
            }
            assert recipe["defaults"]["title"] == name.replace("-", " ").title()
            assert recipe["build"] == generated.recipe["build"]
            assert [book["version"] for book in recipe["books"]] == [
                book["version"] for book in generated.recipe["books"]
            ]


def pep621_dep_names(pyproject: str) -> set[str]:
    """The `depName`s Renovate reads from `[project.dependencies]`.

    Its pep621 manager captures the PEP 508 name and the extras separately, and keeps
    only the name, so a rule naming the extras would match nothing.
    """
    declared = tomllib.loads(pyproject)["project"]["dependencies"]
    named = (re.match(r"[A-Za-z0-9._-]+", requirement) for requirement in declared)
    return {match.group() for match in named if match}


def github_actions_dep_names(workflow: Path) -> set[str]:
    """The `depName`s Renovate reads from a workflow's `uses:` lines.

    Its github-actions manager keeps the owner and the repository, holding a reusable
    workflow's path aside, so a rule naming that path would match nothing.
    """
    calls = (line.removeprefix("uses:").strip() for line in uses_lines(workflow))
    return {"/".join(call.split("@")[0].split("/")[:2]) for call in calls}


def renovate_reaches(config: dict[str, Any], manager: str, dep: str) -> bool:
    """Whether Renovate would still propose an update for a dependency."""
    enabled = True
    for rule in config.get("packageRules", []):
        managers = rule.get("matchManagers")
        deps = rule.get("matchDepNames")
        if (managers is None or manager in managers) and (deps is None or dep in deps):
            enabled = rule.get("enabled", enabled)
    return enabled


def test_generated_renovate_config_leaves_the_copier_owned_pins_alone(
    feedstock: Feedstock,
) -> None:
    """`copier update` owns both pins, so a Renovate bump would split them apart.

    The reusable workflow ref and the SDK pin move together, and the CI caller
    installs the SDK the build resolves, so a one sided bump breaks the upload.
    """
    config = json.loads(feedstock.read("renovate.json"))

    assert config["$schema"] == "https://docs.renovatebot.com/renovate-schema.json"
    assert config["copier"]["enabled"] is True
    assert not renovate_reaches(
        config, "github-actions", "climate-resource/copier-bookshelf-dataset"
    )
    assert not renovate_reaches(config, "pep621", "bookshelf")

    disabled = {
        (manager, dep)
        for rule in config["packageRules"]
        if rule.get("enabled") is False
        for manager in rule["matchManagers"]
        for dep in rule["matchDepNames"]
    }
    assert disabled == {
        ("github-actions", "climate-resource/copier-bookshelf-dataset"),
        ("pep621", "bookshelf"),
    }
    # A rule naming a dependency no manager extracts matches nothing and so protects
    # nothing, so every disabled name has to be one the feedstock really declares.
    extracted = {
        "pep621": pep621_dep_names(feedstock.read("pyproject.toml")),
        "github-actions": github_actions_dep_names(
            feedstock.path / ".github" / "workflows" / "feedstock-ci.yaml"
        ),
    }
    for manager, dep in disabled:
        assert dep in extracted[manager], f"{manager} extracts {extracted[manager]}"

    # The other managers stay reachable, or the feedstock stops getting updates.
    assert renovate_reaches(config, "pep621", "pandas")
    assert renovate_reaches(config, "github-actions", "actions/checkout")
